int main() {
    using namespace totk::travel;
    const auto points = Scan(Scene);
    assert(points.size() == 3);
    assert(points[0].kind == Kind::Lightroot && points[0].state_key == "ArrivalPointState.CheckPoint086");
    assert(std::fabs(points[0].x + 4389.6f) < 0.01f && std::fabs(points[0].z + 3713.8f) < 0.01f);
    assert(points[1].kind == Kind::Shrine && points[1].state_key == "DungeonState.Dungeon021");
    assert(points[2].kind == Kind::Tower && points[2].state_key.empty());
    assert(Scan(std::span<const std::uint8_t>{Scene, 10}).empty());
    std::puts("totk_travel_test: ok");
}
